import logging
import re
import copy


class Event(object):
    def __init__(self, index, status, pattern, entry_type='updates'):
        """
        :param int index: int should be one of Index attributes
        :param Union[dict, list] status: should be one of CellStatuses
        :param str pattern: regex pattern to match distribution name
        :param str entry_type: 'updates' or 'removals'
        """
        self.index = index
        self.status = status if isinstance(status, list) else [status]
        self.pattern = pattern
        self.compiled_pattern = re.compile(pattern) if pattern else None
        self.entry_type = entry_type

    def __str__(self):
        return r"PATTERN: '{}', STATUS: '{}'".format(self.pattern, self.status)


class ChangeEvent(Event):
    def __init__(self, index, status, pattern, entry_type='updates'):
        super(ChangeEvent, self).__init__(index=index, status=status, pattern=pattern, entry_type=entry_type)

    def __deepcopy__(self, memo):
        obj = ChangeEvent(copy.copy(self.index),
                          copy.deepcopy(self.status),
                          copy.copy(self.pattern),
                          copy.copy(self.entry_type))
        obj.compiled_pattern = re.compile(self.pattern)
        return obj


class SiteResetRequest(Event):
    def __init__(self):
        super(SiteResetRequest, self).__init__(index=None, status=None, pattern=None)


class AnyStatus(Event):
    def __init__(self, index, pattern=r'.*', entry_type='updates'):
        super(AnyStatus, self).__init__(index=index, status=None, pattern=pattern, entry_type=entry_type)


class OneOfEvents(object):
    def __init__(self, events, index):
        self.events = events
        self.index = index


class AllEvents(object):
    def __init__(self, events, index):
        self.events = set(events)
        self.index = index
        self._occurred_events = set()

    def add_event_to_occurred(self, event):
        self._occurred_events.add(event)

    def reset(self):
        self._occurred_events = set()

    def all_events_occurred(self):
        return self.events == self._occurred_events


class SequenceOfEvents(object):
    def __init__(self, events):
        self.events = events
        self.current_event_record = None
        self.next_event_record = None
        self._event_copy = None
        self.reset()

    def reset(self):
        self._event_copy = copy.deepcopy(self.events)
        self._update_current_and_next_event_record()

    def _update_current_and_next_event_record(self):
        self.current_event_record = self._event_copy.pop(0)
        self.next_event_record = self._event_copy[0] if self._event_copy else None

    def update_next_event(self, dist_name, values):
        if self.next_event_record is None:
            logging.debug("[SequenceOfEvents] 'next_event_record' is None - skipping updating")
            return

        if not self.current_event_record.get('settings'):
            logging.debug("[SequenceOfEvents] 'settings' not defined - skipping updating")
            self._update_current_and_next_event_record()
            return

        value_to_replace = self._get_value_to_replace(dist_name, values)
        self._set_value(value_to_replace)

        self._update_current_and_next_event_record()

    def _get_value_to_replace(self, dist_name, values):
        current_settings = self.current_event_record['settings']['current']
        if current_settings['attribute'] == 'pattern':
            value_to_replace = dist_name
        else:
            for key in current_settings['path_to_value'].split('->'):
                values = values[key]
            value_to_replace = values

        return value_to_replace

    def _set_value(self, value_to_replace):
        next_settings = self.current_event_record['settings']['next']
        next_attr = getattr(self.next_event_record['event'], next_settings['attribute'])
        if next_settings['attribute'] == 'pattern':
            setattr(self.next_event_record['event'], next_settings['attribute'], value_to_replace)
        else:
            attr_copy = copy.deepcopy(next_attr)
            dict_rec = attr_copy[0]
            value_paths = next_settings['path_to_value'].split('->')
            for index, key in enumerate(value_paths, 1):
                if index == len(value_paths):
                    dict_rec[key] = value_to_replace
                else:
                    dict_rec = dict_rec[key]
            setattr(self.next_event_record['event'], next_settings['attribute'], attr_copy)
